287	                // started meanwhile in another window
288	                return person;
289	            }
290	        } else {
291	            watches.delete(existing.get());
292	            watches.flush();
293	        }
294	        audit.recordOnCommit((on ? "PERSON_WATCHED" : "PERSON_UNWATCHED") + " sheet=" + sheetId + " by=" + name
295	                + " name=" + person.getName());
296	        return person;
297	    }
298	
299	    private void record(String event, String sheetId, String user, Person person, String grade, String tail) {
300	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user.strip()
301	                + " name=" + person.getName() + " grade=" + grade + tail);
302	    }
303	
304	    private void requireUnused(String sheetId, String name, Long self) {
305	        people.findBySheetIdAndNameKey(sheetId, Person.keyOf(name))
306	                .filter(other -> !other.getId().equals(self))
307	                .ifPresent(other -> { throw new DuplicatePersonNameException(); });
308	        if (people.findBySheetIdAndAliasKey(sheetId, Person.keyOf(name)).isPresent()) {
309	            throw new DuplicatePersonNameException();
310	        }
311	    }
312	
313	    private void requireContactUnused(String sheetId, String contact, Long self) {
314	        if (contact == null) return;
315	        people.findBySheetIdAndContact(sheetId, contact)
316	                .filter(other -> !other.getId().equals(self))
317	                .ifPresent(other -> { throw new DuplicatePersonContactException(); });
318	    }
319	
