1	package net.officefloor.hq.app.person;
2	
3	import jakarta.validation.Valid;
4	import jakarta.validation.constraints.NotBlank;
5	import jakarta.validation.constraints.NotEmpty;
6	import jakarta.validation.constraints.NotNull;
7	import jakarta.validation.constraints.Pattern;
8	import jakarta.validation.constraints.Size;
9	import java.time.LocalDate;
10	import java.util.ArrayList;
11	import java.util.List;
12	import java.util.Map;
13	import java.util.Set;
14	import net.officefloor.hq.app.setting.OpenToViewer;
15	import org.springframework.validation.annotation.Validated;
16	import org.springframework.web.bind.annotation.GetMapping;
17	import org.springframework.web.bind.annotation.PathVariable;
18	import org.springframework.web.bind.annotation.PostMapping;
19	import org.springframework.web.bind.annotation.PutMapping;
20	import org.springframework.web.bind.annotation.RequestBody;
21	import org.springframework.web.bind.annotation.RequestHeader;
22	import org.springframework.web.bind.annotation.RequestMapping;
23	import org.springframework.web.bind.annotation.RestController;
24	
25	@RestController
26	@Validated
27	@RequestMapping("/api/sheets/{sheetId}/people")
28	public class PersonController {
29	
30	    /**
31	     * A person as the screen shows them: grade is the one in force on the sheet's today, grades every
32	     * grade recorded, earliest first (the first from null, the beginning of time); retiredFrom is null
33	     * while not retired; held whether they have any hold, holds every hold, earliest first; patronIds
34	     * in the order named; watched whether the signed-in user watches them; terms their own, null for none;
35	     * contact theirs, null for none; aliases theirs, sorted as names are compared; active whether they are active on the sheet's today ({@link Person#activeOn}).
36	     */
37	    public record PersonView(Long id, String name, String grade, List<GradeView> grades, long version,
38	            boolean retired, LocalDate retiredFrom, boolean held, List<HoldView> holds, List<Long> patronIds,
39	            boolean watched, Integer terms, boolean active, String contact, List<String> aliases) {
40	        public static PersonView of(Person person, LocalDate today, List<Long> patronIds, boolean watched,
41	                boolean active) {
42	            List<GradeView> grades = new ArrayList<>();
43	            grades.add(new GradeView(null, person.getGrade()));
44	            person.getDatedGrades().forEach((from, grade) -> grades.add(new GradeView(from, grade)));
45	            return new PersonView(person.getId(), person.getName(),
46	                    today == null ? person.getGrade() : person.gradeOn(today), grades, person.getVersion(),
47	                    person.isRetired(), person.getRetiredFrom(), person.isHeld(),
48	                    person.getHolds().stream().map(h -> new HoldView(h.getFromDate(), h.getToDate())).toList(),
49	                    patronIds, watched, person.getTerms(), active, person.getContact(),
50	                    person.getAliases());
51	        }
52	    }
53	
54	    /** A grade in force from a date (null: the beginning of time). */
55	    public record GradeView(LocalDate from, String grade) {}
56	
57	    /** A hold from a date (null: the beginning of time) to a date (null: open-ended), both included. */
58	    public record HoldView(LocalDate from, LocalDate to) {}
59	
60	    /** A hold to put on a person: from the date (blank: the sheet's today) to the optional to-date. */
61	    public record HoldRequest(LocalDate from, LocalDate to) {}
62	
63	    /** Whether the signed-in user is to watch the person. */
64	    public record WatchRequest(@NotNull Boolean watched) {}
65	
66	    /** An alias to give a person. */
67	    public record AliasRequest(@NotBlank @Size(max = 200) String alias) {}
68	
69	    /** The person to name as a patron. */
70	    public record PatronRequest(@NotNull Long patronId) {}
71	
72	    public record PersonRequest(
73	            @NotBlank @Size(max = 200) String name,
74	            @NotNull @Pattern(regexp = "[ABC]") String grade,
75	            @Pattern(regexp = "\\d{0,4}") String terms,
76	            @Size(max = 200) String contact) {}
77	
78	    /** An edit, made from the version of the person the form loaded. */
79	    public record PersonEditRequest(
80	            @NotBlank @Size(max = 200) String name,
81	            @NotNull @Pattern(regexp = "[ABC]") String grade,
82	            LocalDate gradeFrom,
83	            @Pattern(regexp = "\\d{0,4}") String terms,
84	            @Size(max = 200) String contact,
85	            @NotNull Long version) {}
86	
87	    /** The people to give the grade, from the date (blank: the sheet's today). */
88	    public record BulkGradeRequest(
89	            @NotEmpty List<@NotNull Long> ids,
90	            @NotNull @Pattern(regexp = "[ABC]") String grade,
91	            LocalDate from) {}
92	
93	    /** How many people a bulk grade changed. */
94	    public record BulkGradeResult(int graded) {}
95	
96	    /** Terms in days as the form gave them; blank or null: none. */
97	    private static Integer termsOf(String terms) {
98	        return terms == null || terms.isEmpty() ? null : Integer.valueOf(terms);
99	    }
100	
101	    /** The date a person is retired from (blank: the sheet's today). */
102	    public record RetireRequest(LocalDate from) {}
103	
104	    private final PersonService service;
105	
106	    public PersonController(PersonService service) {
107	        this.service = service;
108	    }
109	
110	    @GetMapping
111	    public List<PersonView> list(
112	            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
113	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
114	        Map<Long, List<Long>> patrons = service.patronIds(sheetId);
115	        Set<Long> watched = service.watchedIds(sheetId, user);
116	        LocalDate today = service.today(sheetId);
117	        Set<Long> active = service.activeIds(sheetId);
118	        return service.list(sheetId).stream()
119	                .map(p -> PersonView.of(p, today, patrons.getOrDefault(p.getId(), List.of()),
120	                        watched.contains(p.getId()), active.contains(p.getId())))
121	                .toList();
122	    }
123	
124	    @PostMapping
125	    public PersonView add(
126	            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
127	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
128	            @RequestBody @Valid PersonRequest request) {
129	        return view(service.add(sheetId, user, request.name(), request.grade(), termsOf(request.terms()),
130	                request.contact()), user);
131	    }
132	
133	    @PutMapping("/{id}")
134	    public PersonView edit(
135	            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
136	            @PathVariable Long id,
137	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
138	            @RequestBody @Valid PersonEditRequest request) {
139	        return view(service.edit(sheetId, user, id, request.version(), request.name(), request.grade(),
140	                request.gradeFrom(), termsOf(request.terms()), request.contact()), user);
141	    }
142	
143	    /** Give each selected person the grade from the date (blank: the sheet's today), in list order. */
144	    @OpenToViewer
145	    @PostMapping("/grade")
146	    public BulkGradeResult bulkGrade(
147	            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
148	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
149	            @RequestBody @Valid BulkGradeRequest request) {
150	        return new BulkGradeResult(service.bulkGrade(sheetId, user, Set.copyOf(request.ids()), request.grade(),
151	                request.from()));
152	    }
153	
154	    @PostMapping("/{id}/retire")
155	    public PersonView retire(
156	            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
157	            @PathVariable Long id,
158	            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
159	            @RequestBody RetireRequest request) {
160	        return view(service.retire(sheetId, user, id, request.from()), user);
161	    }
162	
163	    /** Put the person on hold from a date to an optional to-date. */
164	    @PostMapping("/{id}/hold")
165	    public PersonView hold(
