package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimBinding;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.LateCharge;
import net.officefloor.hq.app.claim.Rounding;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateService;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The statements taken for people on a sheet. Taking one records the person's due-total at that
 * moment (late charges included, at most the sheet's cap) and binds each of their claims that counts to the figure it has
 * then, without its late charge, which keeps following the sheet's today; their other claims
 * are left unbound, their due live again. A claim's due fixed when settled stays as it is.
 * A steward can cancel a person's last statement: the claims it bound are live again (a figure bound
 * by a statement before it is not restored) and the statement before it is their last.
 * A statement can also be taken as of an earlier date ({@link #take}); it shows that date as its date.
 */
@Service
public class StatementService {

    /** A person's statements: how many, and the last one's due-total (null when n/a) and date. */
    public record Summary(Long personId, int count, BigDecimal lastDueTotal, LocalDate lastDate) {}

    /** A statement just taken, with the person's claims as they now stand. */
    public record Taken(Summary summary, List<Claim> claims) {}

    private final StatementRepository statements;
    private final PersonRepository people;
    private final ClaimRepository claims;
    private final ClaimService claimService;
    private final RateService rates;
    private final SheetRepository sheets;
    private final RollupService rollup;
    private final SettingService settings;
    private final Audit audit;

    public StatementService(StatementRepository statements, PersonRepository people, ClaimRepository claims,
            ClaimService claimService, RateService rates, SheetRepository sheets, RollupService rollup,
            SettingService settings, Audit audit) {
        this.statements = statements;
        this.people = people;
        this.claims = claims;
        this.claimService = claimService;
        this.rates = rates;
        this.sheets = sheets;
        this.rollup = rollup;
        this.settings = settings;
        this.audit = audit;
    }

    /** Each person's statements on the sheet, for those with any. */
    @Transactional(readOnly = true)
    public List<Summary> summaries(String sheetId) {
        Map<Long, List<Statement>> byPerson = new LinkedHashMap<>();
        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
            byPerson.computeIfAbsent(s.getPersonId(), id -> new ArrayList<>()).add(s);
        }
        return byPerson.entrySet().stream().map(e -> summaryOf(e.getKey(), e.getValue())).toList();
    }

    /**
     * Take a statement for the person now, or as of a date (null: now) on or before the sheet's today and
     * not before they were added. As of a date, it binds their claims that counted at the end of it to
     * their figures as they stood then: every change made while the sheet's today was on or before the
     * date counts, no later one, and the date stands in for the sheet's today in every figure.
     */
    @Transactional
    public Taken take(String sheetId, String user, Long personId, LocalDate asOf) {
        // Lock the sheet so the claims and rates read are not changed while the statement is taken.
        Sheet sheet = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
        LocalDate today = sheet.getToday();
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        if (asOf != null && (asOf.isAfter(today) || !person.existedAt(asOf))) throw new StatementDateException();
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
        Bound bound = asOf == null ? bindNow(sheet, person, theirs) : bindAsOf(sheet, person, theirs, asOf);
        claims.saveAllAndFlush(theirs);
        statements.saveAndFlush(new Statement(sheetId, personId, bound.dueTotal(), asOf != null ? asOf : today, today,
                user.strip()));
        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user.strip() + " name=" + person.getName()
                + " due-total=" + (bound.dueTotal() == null ? "n/a" : bound.dueTotal().toPlainString())
                + " claims=" + bound.counted() + (asOf != null ? " asof=" + asOf : ""));
        rollup.recordChanges(sheetId, user, before);
        return new Taken(summaryOf(personId, statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId)),
                theirs);
    }

    /** What a statement bound: the due-total (null when n/a) and how many claims counted toward it. */
    private record Bound(BigDecimal dueTotal, int counted) {}

    /** Bind the person's claims that count now to their figures now, the rest unbound. */
    private Bound bindNow(Sheet sheet, Person person, List<Claim> theirs) {
        String sheetId = sheet.getId();
        LocalDate today = sheet.getToday();
        boolean fixed = false;
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        int counted = 0;
        for (Claim claim : theirs) {
            if (!person.counts(claim, today)) {
                claim.unstate(today);
                continue;
            }
            BigDecimal figure = claimService.figureOf(sheetId, person, claim);
            BigDecimal due = claimService.chargedFigureOf(sheetId, person, claim);
            if (claim.getSettledDue() != null || (claim.isBound() && claim.getStatedDue() != null)) fixed = true;
            // a due under a grade they had on its date but not today counts like a fixed one
            if (due != null && !person.gradeOn(claim.getDate()).equals(person.gradeOn(today))) fixed = true;
            // and so does a due under a rate that is not the one in force today
            String grade = person.gradeOn(claim.getDate());
            if (due != null && !rates.on(sheetId, grade, claim.getDate()).map(Rate::getId)
                    .equals(rates.on(sheetId, grade, today).map(Rate::getId))) fixed = true;
            claim.state(figure, today);
            if (due != null) total = total.add(due);
            counted++;
        }
        // As on screen: n/a when their grade has no rate today and none of the counted claims has a fixed
        // due, nor a due under another grade they had on its date or under a rate not in force today.
        return new Bound(sheet.capped(
                fixed || rates.on(sheetId, person.gradeOn(today), today).isPresent() ? total : null), counted);
    }

    /**
     * Bind the person's claims that counted at the end of the date to their figures as they stood then, the
     * rest unbound: the status, settled due and binding each had then, their holds and retirement, grades,
     * rates and dated settings as recorded by then, with the date in place of the sheet's today.
     */
    private Bound bindAsOf(Sheet sheet, Person person, List<Claim> theirs, LocalDate asOf) {
        LocalDate today = sheet.getToday();
        Map<String, List<Rate>> ratesThen = rates.asOf(sheet.getId(), asOf);
        Map<String, LocalDate> datesByNumber = Rounding.datesByNumber(theirs);
        boolean fixed = false;
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        int counted = 0;
        for (Claim claim : theirs) {
            ClaimStatus status = claim.statusAt(asOf);
            if (status == null || !status.counts() || claim.isDeferredAt(status, asOf)) {
                claim.unstate(today);
                continue;
            }
            // a PENDING claim showed its live due, unbound
            ClaimBinding binding = status == ClaimStatus.PENDING ? null : claim.bindingAt(asOf);
            if (status.isOpen() && binding == null
                    && (person.heldOn(claim.getDate(), asOf) || person.retiredAt(asOf))) {
                claim.unstate(today);
                continue;
            }
            String grade = person.gradeOn(claim.getDate(), asOf);
            List<Rate> gradeRates = ratesThen.getOrDefault(grade, List.of());
            RoundingMode rounding = Rounding.of(Rounding.basisOf(claim, datesByNumber), sheet.getPolicyDate(), asOf);
            BigDecimal settled = status == ClaimStatus.SETTLED ? claim.settledDueAt(asOf) : null;
            BigDecimal figure = settled != null ? settled
                    : binding != null ? binding.getDue()
                    : Rate.inForce(gradeRates, claim.getDate())
                            .map(rate -> claim.getAmount().multiply(rate.getPct()).movePointLeft(2).setScale(2, rounding))
                            .orElse(null);
            BigDecimal due = figure;
            if (settled == null) {
                if (status.isOpen()) {
                    due = LateCharge.withChargeAsOpen(claim, due, asOf, sheet.graceOn(grade, claim.getDate(), asOf),
                            d -> sheet.latePctOn(d, asOf), rounding);
                }
                if (due != null && !claim.isCorrection()) due = due.max(sheet.floorOn(claim.getDate(), asOf));
            }
            if (settled != null || (binding != null && binding.getDue() != null)) fixed = true;
            // a due under a grade they had on its date but not on the date counts like a fixed one
            if (due != null && !grade.equals(person.gradeOn(asOf, asOf))) fixed = true;
            // and so does a due under a rate that is not the one in force on the date
            if (due != null && !Rate.inForce(gradeRates, claim.getDate()).equals(Rate.inForce(gradeRates, asOf))) {
                fixed = true;
            }
            claim.state(figure, today);
            if (due != null) total = total.add(due);
            counted++;
        }
        boolean rated = Rate.inForce(ratesThen.getOrDefault(person.gradeOn(asOf, asOf), List.of()), asOf).isPresent();
        return new Bound(sheet.cappedAsOf(fixed || rated ? total : null, asOf), counted);
    }

    /** A steward cancels the person's last statement, unbinding the claims it bound. */
    @Transactional
    public Taken cancelLast(String sheetId, String user, Long personId) {
        LocalDate today = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new).getToday();
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new StatementCancelRefusedException();
        List<Statement> theirStatements = new ArrayList<>(statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId));
        if (theirStatements.isEmpty()) throw new StatementCancelRefusedException();
        Statement last = theirStatements.remove(theirStatements.size() - 1);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
        for (Claim claim : theirs) {
            if (claim.isStated()) claim.unstate(today);
        }
        claims.saveAllAndFlush(theirs);
        statements.delete(last);
        statements.flush();
        audit.recordOnCommit("STATEMENT_CANCELLED sheet=" + sheetId + " by=" + user.strip() + " name=" + person.getName()
                + " due-total=" + (last.getDueTotal() == null ? "n/a" : last.getDueTotal().toPlainString()));
        rollup.recordChanges(sheetId, user, before);
        return new Taken(summaryOf(personId, theirStatements), theirs);
    }

    private static Summary summaryOf(Long personId, List<Statement> list) {
        if (list.isEmpty()) return new Summary(personId, 0, null, null);
        Statement last = list.get(list.size() - 1);
        return new Summary(personId, list.size(), last.getDueTotal(), last.getDate());
    }
}
package net.officefloor.hq.app.statement;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A statement taken for a person on a sheet: their due-total at that moment (none when it was n/a),
 * the date it is as of (the sheet's today when it was taken, unless taken as of an earlier date), the
 * sheet's today when it was taken, and who took it.
 */
@Entity
@Table(name = "statement")
public class Statement {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "due_total", precision = 14, scale = 2)
    private BigDecimal dueTotal;

    @Column(name = "statement_date", nullable = false)
    private LocalDate date;

    @Column(name = "taken_on")
    private LocalDate takenOn;

    @Column(name = "taken_by", nullable = false, length = 100)
    private String takenBy;

    protected Statement() {}

    public Statement(String sheetId, Long personId, BigDecimal dueTotal, LocalDate date, LocalDate takenOn,
            String takenBy) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.dueTotal = dueTotal;
        this.date = date;
        this.takenOn = takenOn;
        this.takenBy = takenBy;
    }

    public Long getId() { return id; }

    public String getSheetId() { return sheetId; }

    public Long getPersonId() { return personId; }

    public BigDecimal getDueTotal() { return dueTotal; }

    public LocalDate getDate() { return date; }

    /** The sheet's today when it was taken. */
    public LocalDate getTakenOn() { return takenOn; }

    public String getTakenBy() { return takenBy; }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.OrderBy;
import jakarta.persistence.OrderColumn;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.TreeMap;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;

/**
 * A person on a sheet, with a name and a grade (A, B or C). The name is kept without surrounding
 * spaces and is unique on the sheet without regard to case (by its {@link #keyOf key}). A person
 * given a retirement date is retired at once, whatever the date; none of their claims may be dated
 * after it, and from the day the sheet's today reaches it their open claims, unless bound by a
 * statement, leave the live totals as a hold's do. A person may have several holds over time, each from a from-date to an optional to-date. The grade is dated: the first one
 * given is in force from the beginning of time, and each later one from its from-date. A person may have
 * their own terms in days, which their claims' due-by takes ahead of their grade's and the sheet's. A person
 * may have aliases, which share the names' uniqueness on the sheet.
 */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "name_key", nullable = false)
    private String nameKey;

    @Column(name = "grade", nullable = false)
    private String grade;

    /** The grades recorded after the first, by the date each is in force from. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
    @MapKeyColumn(name = "from_date")
    @Column(name = "grade", nullable = false)
    private Map<LocalDate, String> datedGrades = new TreeMap<>();

    /** Each grade recorded after the first, oldest first, with the sheet's today it was recorded on. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_grade_log", joinColumns = @JoinColumn(name = "person_id"))
    @OrderColumn(name = "seq")
    private List<PersonGradeLine> gradeLog = new ArrayList<>();

    /** The sheet's today when they were added; null when added before this was kept. */
    @Column(name = "added_on", updatable = false)
    private LocalDate addedOn;

    /** The sheet's today when their retirement date was last set; null while not retired, or set before this was kept. */
    @Column(name = "retired_on")
    private LocalDate retiredOn;

    /** Their own terms in days, ahead of their grade's and the sheet's; null: none. */
    @Column(name = "terms")
    private Integer terms;

    /** Their contact, without surrounding spaces and lower-cased; null: none. */
    @Column(name = "contact")
    private String contact;

    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** Their holds, earliest from-date first. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
    @OrderBy("fromDate ASC, toDate ASC")
    private List<PersonHold> holds = new ArrayList<>();

    /** Their aliases, in the order they were added. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_alias", joinColumns = @JoinColumn(name = "person_id"))
    private List<PersonAlias> aliases = new ArrayList<>();

    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {}

    public Person(String sheetId, String name, String grade, LocalDate addedOn) {
        this.sheetId = sheetId;
        setName(name);
        this.grade = grade;
        this.addedOn = addedOn;
    }

    /** The key a name is compared by for uniqueness: without surrounding spaces, lower-cased. */
    public static String keyOf(String name) {
        return name.strip().toLowerCase(Locale.ROOT);
    }

    public Long getId() { return id; }

    public String getSheetId() { return sheetId; }

    public String getName() { return name; }

    public void setName(String name) {
        this.name = name.strip();
        this.nameKey = keyOf(name);
    }

    /** The first grade they were given, in force from the beginning of time. */
    public String getGrade() { return grade; }

    /** The grade in force on the date: the one with the latest from-date on or before it. */
    public String gradeOn(LocalDate date) {
        Map.Entry<LocalDate, String> on = new TreeMap<>(datedGrades).floorEntry(date);
        return on == null ? grade : on.getValue();
    }

    /** Record the grade from the date on the sheet's today, in place of any recorded from the same date. */
    public void setGradeFrom(LocalDate from, String grade, LocalDate on) {
        datedGrades.put(from, grade);
        gradeLog.add(new PersonGradeLine(from, grade, on));
    }

    /**
     * The grade in force on the date as recorded by the end of the as-of date: of the grades recorded while
     * the sheet's today was on or before it, the one with the latest from-date on or before the date.
     */
    public String gradeOn(LocalDate date, LocalDate asOf) {
        TreeMap<LocalDate, String> then = new TreeMap<>();
        for (PersonGradeLine line : gradeLog) if (line.recordedBy(asOf)) then.put(line.getFromDate(), line.getGrade());
        Map.Entry<LocalDate, String> on = then.floorEntry(date);
        return on == null ? grade : on.getValue();
    }

    /** The sheet's today when they were added; null when added before this was kept. */
    public LocalDate getAddedOn() { return addedOn; }

    /** Whether they were on the sheet at the end of the date: added while its today was on or before it. */
    public boolean existedAt(LocalDate date) { return addedOn == null || !addedOn.isAfter(date); }

    /** The grades recorded after the first, by the date each is in force from, earliest first. */
    public Map<LocalDate, String> getDatedGrades() { return new TreeMap<>(datedGrades); }

    /** Their own terms in days, or null when they have none. */
    public Integer getTerms() { return terms; }

    public void setTerms(Integer terms) { this.terms = terms; }

    /** Their contact, or null when they have none. */
    public String getContact() { return contact; }

    public void setContact(String contact) { this.contact = contactOf(contact); }

    /** A contact as it is stored: without surrounding spaces, lower-cased; blank or null: none. */
    public static String contactOf(String contact) {
        if (contact == null || contact.isBlank()) return null;
        return contact.strip().toLowerCase(Locale.ROOT);
    }

    /** Their aliases, sorted as names are compared (by key, then as given). */
    public List<String> getAliases() {
        return aliases.stream()
                .sorted(Comparator.comparing(PersonAlias::getAliasKey).thenComparing(PersonAlias::getAlias))
                .map(PersonAlias::getAlias).toList();
    }

    /** Whether they have the name, as names are compared, as an alias. */
    public boolean hasAlias(String name) {
        String key = keyOf(name);
        return aliases.stream().anyMatch(a -> a.getAliasKey().equals(key));
    }

    public void addAlias(String alias) { aliases.add(new PersonAlias(sheetId, alias)); }

    /** The date they are retired from, or null while not retired. */
    public LocalDate getRetiredFrom() { return retiredFrom; }

    /** Retire them from the date, on the sheet's today. */
    public void retireFrom(LocalDate retiredFrom, LocalDate on) {
        this.retiredFrom = retiredFrom;
        this.retiredOn = on;
    }

    public boolean isRetired() { return retiredFrom != null; }

    /** Whether a claim of theirs may be dated on the date: not after their retirement date. */
    public boolean mayClaimOn(LocalDate date) { return retiredFrom == null || !date.isAfter(retiredFrom); }

    /** Whether they have any hold, whatever its dates. */
    public boolean isHeld() { return !holds.isEmpty(); }

    /** Their holds, earliest from-date first. */
    public List<PersonHold> getHolds() { return List.copyOf(holds); }

    public void addHold(PersonHold hold) { holds.add(hold); }

    /** Whether the date falls within any of their holds. */
    public boolean heldOn(LocalDate date) { return holds.stream().anyMatch(h -> h.contains(date)); }

    /**
     * Whether the date falls within any of their holds put on while the sheet's today was on or before the
     * as-of date.
     */
    public boolean heldOn(LocalDate date, LocalDate asOf) {
        return holds.stream().anyMatch(h -> h.putOnBy(asOf) && h.contains(date));
    }

    /** Whether, as it stood at the end of the date, they were retired by it: retired then, from on or before it. */
    public boolean retiredAt(LocalDate date) {
        return retiredOn(date) && (retiredOn == null || !retiredOn.isAfter(date));
    }

    /** Whether their retirement date is reached on the date (the date on or after it). */
    public boolean retiredOn(LocalDate date) { return retiredFrom != null && date != null && !date.isBefore(retiredFrom); }

    /** Whether an open claim of theirs is kept out of the live totals: dated within a hold, or retired by the sheet's today. */
    private boolean keptOut(Claim claim, LocalDate today) { return heldOn(claim.getDate()) || retiredOn(today); }

    /**
     * Whether a claim of theirs counts in the live totals: it counts by its status, unless it is open
     * (OPEN or PENDING), dated within a hold or theirs once their retirement date is reached on the
     * sheet's today, and not bound by a statement, or deferred on the sheet's today.
     */
    public boolean counts(Claim claim, LocalDate today) {
        if (!claim.getStatus().counts() || claim.isDeferredOn(today)) return false;
        return !claim.getStatus().isOpen() || claim.isBound() || !keptOut(claim, today);
    }

    /**
     * Whether a claim of theirs counts for a period ending on the date: by the status it had at the end
     * of that date, less a deferred one and one still open now (OPEN or PENDING) dated within a hold, or
     * theirs once retired on the sheet's today, and not bound, as the live rules say: a claim since settled or voided is no longer kept out by a hold.
     */
    public boolean countsAt(Claim claim, LocalDate end, LocalDate today) {
        ClaimStatus at = claim.statusAt(end);
        if (at == null || !at.counts() || claim.isDeferredOn(today)) return false;
        return !claim.getStatus().isOpen() || claim.isBound() || !keptOut(claim, today);
    }

    /**
     * Whether they are active on the date: they have an open claim (OPEN or PENDING) that counts, dated
     * within the 30 days up to and including it.
     */
    public boolean activeOn(Iterable<Claim> claims, LocalDate today) {
        if (today == null) return false;
        LocalDate since = today.minusDays(29);
        for (Claim claim : claims) {
            if (!getId().equals(claim.getPersonId()) || !claim.getStatus().isOpen() || !counts(claim, today)) continue;
            if (!claim.getDate().isBefore(since) && !claim.getDate().isAfter(today)) return true;
        }
        return false;
    }

    /** Moved on by each save; an edit is refused unless made from the current version. */
    public long getVersion() { return version; }
}

